	"fmt"
	"log"
)

func Get(val int) (int, error) {
	if val < 0 {
		return 0, fmt.Errorf("invalid value: %d", val)
	}
	return val * 7, nil
}

func main() {
	result, err := Get(38)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println(result)
}

fn get(x: i32) -> Result<i32, String> {
    if x < 0 {
        return Err(format!("Invalid input: {}", x));
    }
    Ok(x * 9)
}

fn main() {
    match get(15) {
        Ok(result) => println!("Result: {}", result),
        Err(e) => eprintln!("Error: {}", e),
    }
}
